CREATE TABLE productos(id VARCHAR(120) PRIMARY KEY,nombre VARCHAR(220) NOT NULL,grade VARCHAR(80) NOT NULL,scale VARCHAR(40) NOT NULL,precio BIGINT NOT NULL,status VARCHAR(20) NOT NULL,imagenes TEXT NOT NULL,descripcion VARCHAR(1200) NOT NULL,preventa BOOLEAN NOT NULL,precio_pie BIGINT NOT NULL,llegada VARCHAR(80) NOT NULL);
CREATE TABLE carritos(owner VARCHAR(320) PRIMARY KEY,items TEXT NOT NULL);
CREATE TABLE ordenes(id VARCHAR(40) PRIMARY KEY,correo VARCHAR(254) NOT NULL,fecha TIMESTAMP(6) NOT NULL,datos TEXT NOT NULL);
CREATE INDEX ix_orden_correo ON ordenes(correo);
